// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 deposit) public {
        deposit = bound(deposit, 0, 1 ether);

        if (deposit > 0) {
            vm.deal(address(this), deposit);
            (bool s, ) = address(c).call{value: deposit}("");
            require(s);
        }

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
